use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclenum! {
# [derive (Copy , Clone , Debug)] enum NodeState < N , S , A : Annotation > { # [doc = " This node has not yet been visited as part of the DFS."] # [doc = ""] # [doc = " After SCC construction is complete, this state ought to be"] # [doc = " impossible."] NotVisited , # [doc = " This node is currently being walked as part of our DFS. It is on"] # [doc = " the stack at the depth `depth` and its current annotation is"] # [doc = " `annotation`."] # [doc = ""] # [doc = " After SCC construction is complete, this state ought to be"] # [doc = " impossible."] BeingVisited { depth : usize , annotation : A } , # [doc = " Indicates that this node is a member of the given cycle where"] # [doc = " the merged annotation is `annotation`."] # [doc = " Note that an SCC can have several cycles, so its final annotation"] # [doc = " is the merged value of all its member annotations."] InCycle { scc_index : S , annotation : A } , # [doc = " Indicates that this node is a member of whatever cycle"] # [doc = " `parent` is a member of. This state is transient: whenever we"] # [doc = " see it, we try to overwrite it with the current state of"] # [doc = " `parent` (this is the \"path compression\" step of a union-find"] # [doc = " algorithm)."] InCycleWith { parent : N } , }
}